mapper.update:
UPDATE rel_release_drill_plan
SET scenario_content = #{scenarioContent},
    environment_content = #{environmentContent},
    updated_by = #{operatorId},
    row_version = row_version + 1
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND deleted = 0
  AND row_version = #{expectedVersion}

mapper.sql:
FROM rel_release_issue i
LEFT JOIN rel_release_drill_round r ON r.id=i.drill_round_id AND r.tenant_id=i.tenant_id AND r.project_id=i.project_id AND r.deleted=0
WHERE i.tenant_id=#{tenantId} AND i.project_id=#{projectId} AND i.deleted=0
 AND (i.issue_no LIKE #{keyword} OR i.issue_title LIKE #{keyword})
 AND i.priority=#{priority}
 AND i.issue_status=#{status}
